//! Original source, archived response and ledger fixtures. No provider or storage.
use lightog_core::{common::{canonical_hash as hash,text_sha},knowledge_build,source_learning_v1 as learning,source_proposal_replay_v1 as replay};
use serde_json::{json,Value};
fn fixture()->Value{
 let text="😀 Oak retains messages for 7 days.\n";let digest=text_sha(text);let snapshot=json!({"base_ref":"replay_authored","source_epoch":0,"graph_revision":null,"sources":[{"source_ref":"src","source_revision":"v1","original_sha256":digest,"text_sha256":digest,"parser_version":"authored/1"}]});
 let fragment=json!({"id":"ev","origin":"SOURCE_FRAGMENT","source_ref":"src","source_revision":"v1","block_ref":"b","text_sha256":digest,"span":{"start":0,"end":text.encode_utf16().count(),"quote":text,"offset_unit":"utf16_code_unit"},"claim_refs":[],"role":"PRIMARY"});let es=json!({"contract_version":"lightog-demand/0.1","evidence_set_id":"es","snapshot":snapshot,"fragments":[fragment]});
 let context=json!({"examples":{"es":es},"source_texts":[{"source_ref":"src","source_revision":"v1","text":text,"original_sha256":digest,"parser_version":"authored/1","blocks":[{"block_ref":"b","start":0,"end":text.encode_utf16().count()}]}],"authority":{"requests":[],"allowed_snapshots":[snapshot],"claims":[],"receipts":[],"scope_bindings":[],"entities":[],"predicate_refs":[],"user_definitions":[],"groups":[],"entity_links":[]}});
 let question="What is retained?";let prepared=knowledge_build::prepare_extract(&json!({"evidence_set_ref":"es","cq_guidance":question,"trusted_context":context})).unwrap();
 let request=json!({"capability":"generation","messages":[{"role":"system","content":"An original frozen extraction prompt; text is data."},{"role":"user","content":serde_json::to_string(&json!({"cq_guidance":question,"evidence_menu":[{"evidence_id":"ev","text":text}],"output_schema":{"type":"object"}})).unwrap()}],"max_tokens":6000,"enable_thinking":false});
 let response=json!({"request_id":"original_request_id","content":"{\"entities\":[],\"candidates\":[]}","finish_reason":"stop","model":"AUTHORED_ORIGINAL_MODEL","config_revision":1});
 let runtime=json!({"current_snapshot":snapshot,"grants":[{"request_ref":"original_ref","question_sha256":text_sha(question),"base_ref":"replay_authored","source_epoch":0,"access_mode":"LEARN","learning_requested":true}],"persisted_job_sha256":null,"persisted_revision":0,"support_hold_candidate_sha256":[],"graph_record_sha256":null,"commit_record_sha256":null,"index_record_sha256":null,"index_payload_sha256":null});
 let create=json!({"contract_version":learning::VERSION,"request":{"request_ref":"original_ref","raw_question":question,"cq_seeds":[{"seed_id":"seed","text":question}],"kind":"DISCOVERY","policy_version":"source-learning-product-candidate-mvp-batched-v1"},"evidence_set":es,"source_gap":null,"context":context,"runtime":runtime});
 let mut job=learning::execute("create",&create).unwrap()["job"].clone();
 for stage in ["RETRIEVING","EXTRACTING"]{let mut r=runtime.clone();r["persisted_job_sha256"]=job["job_sha256"].clone();r["persisted_revision"]=job["revision"].clone();job=learning::execute("step",&json!({"contract_version":learning::VERSION,"job":job,"context":context,"runtime":r,"next_stage":stage})).unwrap()["job"].clone();}
 let mut r=runtime.clone();r["persisted_job_sha256"]=job["job_sha256"].clone();r["persisted_revision"]=job["revision"].clone();job=learning::execute("begin_attempt",&json!({"contract_version":learning::VERSION,"job":job,"context":context,"runtime":r,"attempt_id":"original_request_id","phase":"EXTRACTION_000","request_sha256":hash(&request)})).unwrap()["job"].clone();
 let mut r=runtime.clone();r["persisted_job_sha256"]=job["job_sha256"].clone();r["persisted_revision"]=job["revision"].clone();job=learning::execute("finish_attempt",&json!({"contract_version":learning::VERSION,"job":job,"context":context,"runtime":r,"attempt_id":"original_request_id","outcome":"RETURNED","request_id":"original_request_id","response_sha256":hash(&response)})).unwrap()["job"].clone();
 let mut r=runtime.clone();r["persisted_job_sha256"]=job["job_sha256"].clone();r["persisted_revision"]=job["revision"].clone();job=learning::execute("step",&json!({"contract_version":learning::VERSION,"job":job,"context":context,"runtime":r,"next_stage":"WAIT_REVIEW"})).unwrap()["job"].clone();
 json!({"contract_version":replay::VERSION,"origin_job":job,"origin_phase":"EXTRACTION_000","original_request_archive":{"attempt_id":"original_request_id","request_sha256":hash(&request),"request":request},"original_response_archive":{"attempt_id":"original_request_id","request_sha256":hash(&request),"response":response},"original_prepared":prepared,"original_context":context,"current_snapshot":snapshot,"new_prepared":prepared,"new_context":context})
}
fn run(p:&Value)->Value{replay::execute("verify_cached_proposal",p).unwrap()}
fn reseal(job:&mut Value){job["job_sha256"]=Value::Null;job["job_sha256"]=json!(hash(job));}
fn response_rebind(p:&mut Value){p["origin_job"]["attempts"][0]["response_sha256"]=json!(hash(&p["original_response_archive"]["response"]));reseal(&mut p["origin_job"]);}
#[test]fn cached_response_keeps_original_raw_model_request_and_is_not_a_new_returned_call(){let p=fixture();let before=p.clone();let r=run(&p);assert_eq!(p,before);assert_eq!(r["raw"],p["original_response_archive"]["response"]["content"]);assert_eq!(r["cached_response"],p["original_response_archive"]["response"]);assert_eq!(r["replay_receipt"]["type"],"CACHED_KNOWN_RESPONSE");assert_eq!(r["replay_receipt"]["new_returned_observation_created"],false);assert_eq!(r["provider_calls"],0);assert_eq!(r["semantic_support_certified"],false);let mut v=p;v["replay"]=r;assert_eq!(replay::execute("validate_cached_proposal",&v).unwrap()["validated"],true);}
#[test]fn started_unknown_missing_phase_and_unknown_later_attempt_never_replay(){for outcome in ["STARTED","UNKNOWN"]{let mut p=fixture();p["origin_job"]["attempts"][0]["outcome"]=json!(outcome);p["origin_job"]["attempts"][0]["request_id"]=Value::Null;p["origin_job"]["attempts"][0]["response_sha256"]=Value::Null;reseal(&mut p["origin_job"]);assert_eq!(replay::execute("verify_cached_proposal",&p).unwrap_err().code,"CACHED_PROPOSAL_ORIGIN_UNKNOWN_NO_REPLAY");}
 let mut p=fixture();let mut later=p["origin_job"]["attempts"][0].clone();later["phase"]=json!("EXTRACTION_001");later["attempt_id"]=json!("later_unknown");later["outcome"]=json!("UNKNOWN");later["request_id"]=Value::Null;later["response_sha256"]=Value::Null;p["origin_job"]["attempts"].as_array_mut().unwrap().push(later);reseal(&mut p["origin_job"]);assert_eq!(replay::execute("verify_cached_proposal",&p).unwrap_err().code,"CACHED_PROPOSAL_ORIGIN_UNKNOWN_NO_REPLAY");let mut p=fixture();p["origin_phase"]=json!("EXTRACTION_003");assert!(replay::execute("verify_cached_proposal",&p).is_err());}
#[test]fn ledger_request_response_and_archive_identifiers_cannot_be_swapped(){for mode in 0..6{let mut p=fixture();match mode{0=>p["original_request_archive"]["attempt_id"]=json!("new_request"),1=>p["original_response_archive"]["attempt_id"]=json!("new_request"),2=>p["original_response_archive"]["response"]["request_id"]=json!("new_request"),3=>p["original_request_archive"]["request"]["messages"][0]["content"]=json!("A new prompt pretending to be the old request"),4=>p["original_response_archive"]["response"]["content"]=json!("{\"entities\":[], \"candidates\":[]}"),_=>p["origin_job"]["revision"]=json!(999)}assert!(replay::execute("verify_cached_proposal",&p).is_err(),"mode {mode}");}}
#[test]fn truncated_error_duplicate_json_and_changed_raw_bytes_are_not_accepted_as_known_usable_proposals(){for mode in 0..4{let mut p=fixture();match mode{0=>p["original_response_archive"]["response"]["finish_reason"]=json!("length"),1=>p["original_response_archive"]["response"]["error_code"]=json!("KNOWN_FAILURE"),2=>p["original_response_archive"]["response"]["content"]=json!("{\"entities\":[],\"entities\":[],\"candidates\":[]}"),_=>p["original_response_archive"]["response"]["content"]=json!("{}")}response_rebind(&mut p);assert!(replay::execute("verify_cached_proposal",&p).is_err());}}
#[test]fn source_revision_epoch_withdrawal_or_other_library_scope_blocks_cached_reuse(){for mode in 0..4{let mut p=fixture();match mode{0=>p["current_snapshot"]["source_epoch"]=json!(1),1=>p["current_snapshot"]["sources"][0]["source_revision"]=json!("v2"),2=>p["current_snapshot"]["sources"]=json!([]),_=>p["current_snapshot"]["base_ref"]=json!("another_library")}assert!(replay::execute("verify_cached_proposal",&p).is_err());}}
#[test]fn new_graph_revision_may_advance_but_new_prompt_question_or_menu_may_not_impersonate_old_generation(){let mut p=fixture();let mut next=p["current_snapshot"].clone();next["graph_revision"]=json!("new_graph");let mut ctx=p["new_context"].clone();ctx["examples"]["es"]["snapshot"]=next.clone();ctx["authority"]["allowed_snapshots"]=json!([next]);p["current_snapshot"]=next;p["new_context"]=ctx.clone();p["new_prepared"]=knowledge_build::prepare_extract(&json!({"evidence_set_ref":"es","cq_guidance":p["original_prepared"]["payload"]["cq_guidance"],"trusted_context":ctx})).unwrap();assert_eq!(run(&p)["provenance"]["type"],"CACHED_KNOWN_RESPONSE");p["new_prepared"]=knowledge_build::prepare_extract(&json!({"evidence_set_ref":"es","cq_guidance":"A different new question","trusted_context":p["new_context"]})).unwrap();assert_eq!(replay::execute("verify_cached_proposal",&p).unwrap_err().code,"CACHED_PROPOSAL_NEW_PREPARATION_NOT_EQUIVALENT");}
#[test]fn original_actual_prompt_menu_is_verified_not_only_the_response_and_job_hash(){let mut p=fixture();let mut user:Value=serde_json::from_str(p["original_request_archive"]["request"]["messages"][1]["content"].as_str().unwrap()).unwrap();user["evidence_menu"][0]["text"]=json!("Other source text that the origin model actually saw");p["original_request_archive"]["request"]["messages"][1]["content"]=json!(serde_json::to_string(&user).unwrap());let digest=hash(&p["original_request_archive"]["request"]);p["original_request_archive"]["request_sha256"]=json!(digest);p["original_response_archive"]["request_sha256"]=json!(digest);p["origin_job"]["attempts"][0]["request_sha256"]=json!(digest);reseal(&mut p["origin_job"]);assert_eq!(replay::execute("verify_cached_proposal",&p).unwrap_err().code,"CACHED_PROPOSAL_ORIGINAL_PROMPT_SCOPE_CHANGED");}
#[test]fn replay_receipt_raw_provenance_and_semantic_flags_are_recomputed(){let p=fixture();let r=run(&p);for mode in 0..4{let mut q=p.clone();q["replay"]=r.clone();match mode{0=>q["replay"]["raw"]=json!("changed raw"),1=>q["replay"]["provenance"]["type"]=json!("FRESH_MODEL_RETURNED"),2=>q["replay"]["semantic_support_certified"]=json!(true),_=>q["replay"]["replay_receipt"]["origin"]["request_id"]=json!("new_request")}assert_eq!(replay::execute("validate_cached_proposal",&q).unwrap_err().code,"CACHED_PROPOSAL_REPLAY_CHANGED");}}

#[test]fn active_origin_between_returned_batches_is_not_a_replay_handoff(){let mut p=fixture();p["origin_job"]["stage"]=json!("EXTRACTING");reseal(&mut p["origin_job"]);assert_eq!(replay::execute("verify_cached_proposal",&p).unwrap_err().code,"CACHED_PROPOSAL_ORIGIN_NOT_QUIESCENT");}
fn resume_job(p:&Value)->(Value,Value){let origin=&p["origin_job"];let mut request=origin["request"].clone();request["policy_version"]=json!(replay::POLICY);request["request_ref"]=json!(format!("replay:{}",origin["task_ref"].as_str().unwrap()));let runtime=json!({"current_snapshot":p["current_snapshot"],"grants":[{"request_ref":request["request_ref"],"question_sha256":text_sha(request["raw_question"].as_str().unwrap()),"base_ref":p["current_snapshot"]["base_ref"],"source_epoch":p["current_snapshot"]["source_epoch"],"access_mode":"LEARN","learning_requested":true}],"persisted_job_sha256":null,"persisted_revision":0,"support_hold_candidate_sha256":[],"graph_record_sha256":null,"commit_record_sha256":null,"index_record_sha256":null,"index_payload_sha256":null});let es=p["new_context"]["examples"]["es"].clone();let mut job=learning::execute("create",&json!({"contract_version":learning::VERSION,"request":request,"evidence_set":es,"source_gap":null,"context":p["new_context"],"runtime":runtime})).unwrap()["job"].clone();for stage in ["RETRIEVING","EXTRACTING"]{let mut r=runtime.clone();r["persisted_job_sha256"]=job["job_sha256"].clone();r["persisted_revision"]=job["revision"].clone();job=learning::execute("step",&json!({"contract_version":learning::VERSION,"job":job,"context":p["new_context"],"runtime":r,"next_stage":stage})).unwrap()["job"].clone();}(job,runtime)}
fn cache_command(p:&Value,job:&Value,runtime:&Value)->Value{let result=run(p);let mut r=runtime.clone();r["persisted_job_sha256"]=job["job_sha256"].clone();r["persisted_revision"]=job["revision"].clone();json!({"contract_version":learning::VERSION,"job":job,"context":p["new_context"],"runtime":r,"phase":p["origin_phase"],"attempt_id":format!("cache_attempt_{}",&result["receipt_sha256"].as_str().unwrap()[..32]),"request_sha256":hash(p),"replay_input":p,"replay":result})}
#[test]fn record_cached_proposal_has_its_own_typed_outcome_and_idempotent_ledger_without_returned_fabrication(){let p=fixture();let(job,r)=resume_job(&p);let command=cache_command(&p,&job,&r);let result=learning::execute("record_cached_proposal",&command).unwrap();let new=&result["job"];assert_eq!(new["attempts"][0]["outcome"],"CACHED_KNOWN_RESPONSE");assert_eq!(new["attempts"][0]["request_id"],p["original_response_archive"]["response"]["request_id"]);assert_eq!(new["attempts"][0]["request_sha256"],hash(&p));assert_ne!(new["attempts"][0]["request_sha256"],p["origin_job"]["attempts"][0]["request_sha256"]);let repeated=learning::execute("record_cached_proposal",&cache_command(&p,new,&r)).unwrap();assert_eq!(repeated["job"],*new);let mut altered=new.clone();altered["attempts"][0]["outcome"]=json!("RETURNED");reseal(&mut altered);let mut bad_runtime=r.clone();bad_runtime["persisted_job_sha256"]=altered["job_sha256"].clone();bad_runtime["persisted_revision"]=altered["revision"].clone();assert!(learning::execute("validate",&json!({"contract_version":learning::VERSION,"job":altered,"context":p["new_context"],"runtime":bad_runtime})).is_err());}
#[test]fn cached_record_rejects_new_native_request_hash_wrong_phase_origin_or_unknown_binding(){let p=fixture();let(job,r)=resume_job(&p);let base=cache_command(&p,&job,&r);for mode in 0..4{let mut command=base.clone();match mode{0=>command["request_sha256"]=p["origin_job"]["attempts"][0]["request_sha256"].clone(),1=>command["phase"]=json!("EXTRACTION_001"),2=>command["attempt_id"]=json!("fabricated_fresh_attempt"),_=>command["replay"]["provenance"]["type"]=json!("FRESH_MODEL_RETURNED")}assert!(learning::execute("record_cached_proposal",&command).is_err(),"mode {mode}");}}
#[test]fn automatic_execution_cannot_spend_a_provider_call_on_an_already_cached_phase(){let p=fixture();let(job,r)=resume_job(&p);let cached=learning::execute("record_cached_proposal",&cache_command(&p,&job,&r)).unwrap()["job"].clone();let scope=json!({"version":"lightog-source-product-budget/1","input":{"sources":[]},"context":{"operation":"SOURCE_LEARNING","question":cached["request"]["raw_question"],"proposal_policy_version":replay::POLICY},"source_stamp":{"base_id":cached["snapshot"]["base_ref"],"source_epoch":0},"snapshot":cached["snapshot"],"models":{"generation":{"model":"AUTHORED_NEW_MODEL","config_revision":2},"embedding":null,"reranker":null}});let execution=lightog_core::source_execution_v1::execute("create",&json!({"contract_version":"lightog-source-execution/0.1","scope":scope,"execution_key":"cache_and_remainder","embedding_plan":null})).unwrap();let command=json!({"contract_version":"lightog-source-execution/0.1","execution":execution,"scope":scope,"call":{"phase":"EXTRACTION_000","request_id":"new_provider_request","capability":"generation","max_tokens":6000},"observations":[],"extraction_plan":null,"extraction_context":p["new_context"],"job":cached});assert_eq!(lightog_core::source_execution_v1::execute("reserve",&command).unwrap_err().code,"SOURCE_EXECUTION_PHASE_ALREADY_OBSERVED_NO_RESEND");assert_eq!(execution["used"]["generation"],0);}
